param([Parameter(Mandatory)][string]$HistoryRoot,[string]$ProjectRoot=(Join-Path $PSScriptRoot '..'),[string]$BuildRoot='')
$ErrorActionPreference='Stop';$ProjectRoot=[IO.Path]::GetFullPath($ProjectRoot);$HistoryRoot=[IO.Path]::GetFullPath($HistoryRoot);if(!(Test-Path (Join-Path $HistoryRoot .synthetic-chat-history))){throw 'Only a synthetic history fixture is accepted'};if(!$BuildRoot){$BuildRoot=Join-Path $ProjectRoot out/release}
$root=Join-Path $ProjectRoot ('artifacts/chat-media-vision-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $root|Out-Null;Copy-Item -LiteralPath (Join-Path $HistoryRoot data) -Destination (Join-Path $root data) -Recurse;$service=$null;$provider=$null;$checks=0;$env:HIBERNATION_SESSION_KEY='chat-media-vision-fixture';$env:TEMP=Join-Path $BuildRoot tmp;$env:TMP=$env:TEMP
function Check($Value,$Name){if(!$Value){throw "CHECK FAILED: $Name"};$script:checks++;Write-Output "PASS $Name"}
function Await([scriptblock]$Probe,$Name){$end=[DateTime]::UtcNow.AddSeconds(25);while([DateTime]::UtcNow-lt$end){if(&$Probe){return};Start-Sleep -Milliseconds 30};throw "TIMEOUT $Name"}
function Api($Path,$Data=$null){$p=@{Uri=$script:origin+$Path;Headers=@{Authorization='Bearer chat-media-vision-fixture'};TimeoutSec=10};if($null-ne$Data){$p.Method='Post';$p.ContentType='application/json';$p.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 40 -Compress))};Invoke-RestMethod @p}
function Plan($Source,$Attachment){$calls=@{version=1;kind='call';text=$null;calls=@(@{id='attachment';tool='chat.view_media';args=@{source_id=$Source;id=$Attachment}})};$reply=@{version=1;kind='reply';text='附件检查已完成。';calls=@()};@{nonce=[Guid]::NewGuid().ToString('N');responses=@(@{response=$calls},@{response=$reply})}|ConvertTo-Json -Depth 30|Set-Content (Join-Path $providerRoot plan.json)}
function Message($Files){$accepted=Api '/api/message' @{request_id=[Guid]::NewGuid().ToString('N');text='synthetic media input';attachments=$Files};Await {!(Api '/api/chat/status').busy} 'media turn';Check (!(Api '/api/chat/status').call_failed) 'media turn completes';return $accepted}
function Capture{Get-Content (Join-Path $providerRoot last-request.json) -Raw|ConvertFrom-Json -Depth 60}
function Feedback{$content=(Capture).messages[-1].content;if($content-isnot[string]){$content=$content[0].text};($content|ConvertFrom-Json -Depth 40).tool_results[0]}
try{
 $providerRoot=Join-Path $root provider;$provider=Start-Process (Join-Path $BuildRoot Hibernation_TestProvider.exe) -ArgumentList ('"'+$providerRoot+'"') -WindowStyle Hidden -PassThru;Await {Test-Path (Join-Path $providerRoot port)} 'provider';$endpoint='http://127.0.0.1:'+(Get-Content (Join-Path $providerRoot port))
 $cfg=Get-Content (Join-Path $HistoryRoot config.json) -Raw|ConvertFrom-Json -AsHashtable;$cfg.dataRoot=Join-Path $root data;$cfg.profiles+=@(@{id='media';label='Synthetic media';enabled=$true;protocol='chat-completions';origin=$endpoint;model='fixture-model';supportsVision=$true;supportsJsonObject=$true},@{id='review';label='Synthetic review';enabled=$true;protocol='chat-completions';origin=$endpoint;model='fixture-reviewer';supportsVision=$true});$cfg.review=@{enabled=$true;profileId='review';maxRewrites=1};$cfg.contextControl=@{preset='full'};$cfg|ConvertTo-Json -Depth 40|Set-Content (Join-Path $root config.json)
 @{nonce='media-review';responses=@(@{response=@{decision='approve';reason='ok';guidance=''}})}|ConvertTo-Json -Depth 10|Set-Content (Join-Path $providerRoot review-plan.json)
 $service=Start-Process (Join-Path $BuildRoot hibernation-agent.exe) -ArgumentList ('--config "'+$root+'/config.json" --ready-file "'+$root+'/ready.json"') -WindowStyle Hidden -PassThru -RedirectStandardError (Join-Path $root error.log);Await {if($service.HasExited){throw 'media backend exited'};Test-Path (Join-Path $root ready.json)} 'backend';$script:origin='http://127.0.0.1:'+((Get-Content (Join-Path $root ready.json) -Raw|ConvertFrom-Json).port);$null=Api '/api/model' @{id='media'}
 $files=(Get-Content (Join-Path $HistoryRoot fixture.json) -Raw|ConvertFrom-Json).media;Plan '${event_id}' $files[0].id;$null=Message @($files[0].id);$capture=Capture;$feedback=Feedback;Check ($feedback.ok-and$feedback.result.image_attached-and$capture.messages[-1].content[1].image_url.url.StartsWith('data:image/jpeg;base64,')) 'actor receives actual encrypted attachment pixels as an image part';Check (!$capture.messages[-1].content[0].text.Contains('base64')) 'pixel bytes stay outside textual receipts'
 $review=Get-Content (Join-Path $providerRoot review-last-request.json) -Raw|ConvertFrom-Json -Depth 60;Check ($review.messages[-1].content[1].image_url.url.StartsWith('data:image/jpeg;base64,')) 'reviewer receives the same attachment evidence'
 Plan 'private-tool' $files[0].id;$null=Message @($files[0].id);Check (!(Feedback).ok-and(Feedback).error.code-eq'chat_media_not_accessible') 'ungranted archive sources cannot retrieve attachments'
 Plan '${event_id}' $files[2].id;$null=Message @($files[2].id);Check (!(Feedback).ok-and(Feedback).error.code-eq'chat_media_image_unavailable') 'video preview is not presented as a model image observation'
 $settings=(Api '/api/dashboard').settings;$settings.profiles.Where({$_.id-eq'media'})[0].supportsVision=$false;$null=Api '/api/settings' @{settings=$settings};Plan '${event_id}' $files[1].id;$null=Message @($files[1].id);Check (!(Feedback).ok-and(Feedback).error.code-eq'vision_not_enabled') 'text-only connection receives an explicit unavailable receipt'
 $null=Api '/api/shutdown' @{};Check ($service.WaitForExit(10000)) 'media fixture stops';@{completed=$true;checks=$checks;production_archive_read=$false;root=$root}|ConvertTo-Json|Set-Content (Join-Path $root acceptance.json)
}finally{if($service-and!$service.HasExited){try{$null=Api '/api/shutdown' @{};$service.WaitForExit(5000)|Out-Null}catch{}};if($provider-and!$provider.HasExited){Stop-Process -Id $provider.Id}}
